<?php require_once __DIR__.'/../app/db.php'; require_once __DIR__.'/../app/layout.php'; require_login(); require_perm('paiements'); $pdo=pdo();
if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare('INSERT INTO paiements(reservation_id,montant,methode,date_paiement,note) VALUES(?,?,?,?,?)')->execute([post('reservation_id'),post('montant'),post('methode'),post('date_paiement'),post('note')]); $paid=$pdo->prepare('SELECT COALESCE(SUM(montant),0) FROM paiements WHERE reservation_id=?');$paid->execute([post('reservation_id')]);$sum=$paid->fetchColumn(); $tot=$pdo->prepare('SELECT total FROM reservations WHERE id=?');$tot->execute([post('reservation_id')]);$total=$tot->fetchColumn(); $pdo->prepare('UPDATE reservations SET avance=?, reste=? WHERE id=?')->execute([$sum,max(0,$total-$sum),post('reservation_id')]); flash('Paiement enregistré.'); redirect('/paiements.php');}
$res=$pdo->query("SELECT r.id, CONCAT(r.reference,' - ',c.nom,' ',c.prenom,' - reste ',r.reste,' DH') label FROM reservations r JOIN clients c ON c.id=r.client_id ORDER BY r.id DESC")->fetchAll();
$rows=$pdo->query("SELECT p.*, r.reference, CONCAT(c.nom,' ',c.prenom) client FROM paiements p JOIN reservations r ON r.id=p.reservation_id JOIN clients c ON c.id=r.client_id ORDER BY p.id DESC")->fetchAll(); render_header('Paiements'); ?>
<section class="panel"><div class="panel-head"><h2>Enregistrer un paiement</h2></div><form method="post" class="form-grid"><label>Réservation<select name="reservation_id"><?php foreach($res as $r):?><option value="<?=$r['id']?>"><?=e($r['label'])?></option><?php endforeach;?></select></label><label>Montant<input type="number" step="0.01" name="montant" required></label><label>Méthode<select name="methode"><option>Espèces</option><option>Carte bancaire</option><option>Virement</option><option>Chèque</option></select></label><label>Date<input type="date" name="date_paiement" value="<?=date('Y-m-d')?>"></label><label class="span2">Note<textarea name="note"></textarea></label><button class="btn primary">Enregistrer paiement</button></form></section><section class="panel"><h2>Historique des paiements</h2><table><thead><tr><th>Date</th><th>Réservation</th><th>Client</th><th>Montant</th><th>Méthode</th></tr></thead><tbody><?php foreach($rows as $p):?><tr><td><?=e($p['date_paiement'])?></td><td><?=e($p['reference'])?></td><td><?=e($p['client'])?></td><td><?=money($p['montant'])?></td><td><?=e($p['methode'])?></td></tr><?php endforeach;?></tbody></table></section><?php render_footer(); ?>
